-- Applied data correction, Luis approval 13 November 2026 14:22 UTC.
-- Exact nine-block before/after content. No schema or commercial changes.
BEGIN;
DO $edit$ DECLARE n integer; BEGIN
IF public.pm_project_b1_active() THEN RAISE EXCEPTION 'B1 must remain OFF'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.</p><p>A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,<span style=\"font-size: 14px;\">&nbsp;submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.</span></p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><ul><li><p>Informação prestada pelo promotor;</p></li><li><p>Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</p></li><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p><strong>[Descrição do edifício existente e quadro de áreas – a completar.]</strong></p><p>Da análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Reabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;</p></li><li><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p></li><li><p><strong>Repartição de responsabilidades:</strong> a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</p></li></ul><p><strong>NOTA:</strong> As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.</p></li></ul><p></p>", "text": "\n\nA nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.\n\n\n\nA Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,\n\n submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.\n\n\n\n\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\n\n\n\n\n\n\nInformação prestada pelo promotor;\n\n\n\n\n\n\n\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\n\n\n\n\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\n\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\n\n\n\n\n\n\n\n\n[Descrição do edifício existente e quadro de áreas – a completar.]\n\n\n\n\n\nDa análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\n\n\nReabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\n\n\n\n\nO número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;\n\n\n\n\n\n\n\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\n\n\n\n\n\n\n\n\n\nRepartição de responsabilidades:\n\n a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.\n\n\n\n\n\n\n\n\n\nNOTA:\n\n As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.\n\n\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\n\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\n\n\n\n\nO acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.\n\n\n\n\n\n\n\n\n\n"}'::jsonb WHERE id='865c7a9f-fe66-4f62-8898-d08a8d80cbe6' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"html": "<p>A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio,<span style=\"font-size: 14px;\">&nbsp;submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.</span></p><p>A proposta apresentada assenta na seguinte informação sobre o edifício existente:</p><p>Informação prestada pelo promotor<span style=\"font-size: 14px;\">;</span></p><p><span style=\"font-size: 14px;\">Conceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;</span></p><ul><li><p>Consulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;</p></li><li><p>Análise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.</p></li></ul><p><strong>[Descrição do edifício existente e quadro de áreas – a completar.]</strong></p><p>Da análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:</p><ul><li><p>Reabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);</p></li><li><p>O número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;</p></li><li><p>Em cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.</p></li><li><p><strong>Repartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&amp;E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.</strong></p></li><li><p><strong>NOTA:</strong><span style=\"font-size: 14px;\"> As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.</span></p></li></ul><p><strong>NOTA:</strong> As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.</p><p>Para além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:</p><ul><li><p>A coordenação dos diversos projetos de especialidades com o projeto de arquitetura;</p></li><li><p>A representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;</p></li><li><p>O acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.</p></li></ul><p></p>", "text": "A nossa proposta refere-se à elaboração dos estudos e Projecto de Arquitectura e Assistência Técnica à execução da obra de reabilitação de um edifício localizado na esquina da Rua Nova do Almada com as Escadinhas de São Francisco (Rua Nova do Almada, 63-73, 1200-288 Lisboa), freguesia da Misericórdia, com o objetivo de o converter num estabelecimento hoteleiro.A Pedra Silva Arquitectos (PSA) será a autora do projeto de arquitetura e a equipa projetista responsável pelo processo, trabalhando em parceria com o designer de interiores indicado pelo Cliente. A PSA irá desenvolver o estudo prévio, submeter o Pedido de Informação Prévia e o processo de licenciamento, preparar o projeto de execução, coordenar todos os projetos de especialidades e prestar assistência técnica à obra.\n\nA proposta apresentada assenta na seguinte informação sobre o edifício existente:\n\nInformação prestada pelo promotor;\n\nConceito de design de interiores a fornecer pelo designer de interiores indicado pelo Cliente;\n\n\n\n\n\nConsulta ao portal LXi para tomar conhecimento das condicionantes urbanísticas do edifício;\n\n\n\nAnálise das condicionantes para estabelecer um cenário possível de intervenção e, com isso, a prestação de serviços necessária para o promotor.\n\n[Descrição do edifício existente e quadro de áreas – a completar.]\n\nDa análise das condicionantes do local, apresentamos uma proposta de prestação de serviços assente nas seguintes premissas:\n\n\n\n\n\nReabilitação do edifício existente para instalação de um hotel, a licenciar como empreendimento turístico nos termos do Regime Jurídico dos Empreendimentos Turísticos (Decreto-Lei n.º 39/2008, na sua redação atual);\n\n\n\nO número e a tipologia das unidades de alojamento, bem como as áreas comuns e de serviço, serão confirmados com o promotor e o designer de interiores na fase de Programa;\n\n\n\nEm cada fase, a PSA só poderá desenvolver o seu trabalho após a receção dos elementos necessários por parte do Cliente e do designer de interiores. Caso estes elementos não sejam recebidos nos prazos acordados, a PSA não poderá ser responsabilizada por atrasos ou incumprimento de prazos.\n\n\n\nRepartição de responsabilidades: a PSA é responsável pelo projeto de arquitetura do edifício, incluindo as áreas técnicas e de serviço, a integração das soluções de interiores nos projetos de licenciamento e de execução e a coordenação geral das especialidades; o designer de interiores indicado pelo Cliente é responsável pelo conceito e projeto de design de interiores dos quartos e das áreas comuns, incluindo mobiliário, equipamento e decoração (FF&E) e iluminação decorativa. A fronteira detalhada entre os dois âmbitos será confirmada na fase de Programa.\n\n\n\nNOTA: As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.\n\nNOTA: As áreas indicadas servem de orientação para a elaboração da proposta de honorários e serão confirmadas com o levantamento arquitetónico do edifício.\n\nPara além do projeto de Arquitetura e Plano de Acessibilidades, faz parte desta proposta:\n\n\n\n\n\nA coordenação dos diversos projetos de especialidades com o projeto de arquitetura;\n\n\n\nA representação do requerente no portal Loja Lisboa e as submissões dos projetos no portal;\n\n\n\nO acompanhamento do parecer do Turismo de Portugal, I.P., no âmbito do licenciamento do estabelecimento hoteleiro.\n\n"}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch 865c7a9f-fe66-4f62-8898-d08a8d80cbe6'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Levantamento arquitetónico do edifício, por técnico credenciado\nDesenhos existentes do edifício em formato DWG (editável), quando disponíveis\nPrograma e objetivos do promotor e normas do operador hoteleiro\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Síntese das condicionantes urbanísticas e regulamentares.\nPrograma do hotel (unidades de alojamento, áreas comuns e de serviço), desenvolvido com o Cliente e o designer de interiores.", "headingLevel": "h2", "objective_html": "<p>O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.</p><p>Nesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.</p>", "objective_text": "O Programa faz parte desta prestação de serviços e é desenvolvido pela PSA em conjunto com o Cliente e o designer de interiores por ele indicado.\n\nNesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente e o designer de interiores;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente e o designer de interiores;\n\n\n\n\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p><p><strong>NOTA:</strong> Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.\n\nNOTA: Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado."}'::jsonb WHERE id='db9736ec-ce7b-4482-8750-5a234a3b4be2' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"client_info": "Levantamento arquitetónico do edifício, por técnico credenciado\nProjeto entregue na CML em formato DWG (editável)\nPrograma e objetivos do promotor e normas do operador hoteleiro\nLimites orçamentais da obra\nDocumentação do imóvel (caderneta predial e certidão do registo predial)", "deliverables": "Síntese das condicionantes urbanísticas e regulamentares.\nComentários técnicos ao programa definido pelo Cliente e pelo Rockwell Group.", "headingLevel": "h2", "objective_html": "<p>O Programa Base não faz parte desta prestação de serviços: é definido pelo Cliente em conjunto com o Rockwell Group, responsável pela conceção do hotel.</p><p>Nesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – o projeto já entregue na Câmara Municipal de Lisboa, as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.</p>", "objective_text": "O Programa Base não faz parte desta prestação de serviços: é definido pelo Cliente em conjunto com o Rockwell Group, responsável pela conceção do hotel.\n\nNesta fase, a PSA reúne e analisa toda a informação relevante para o desenvolvimento do Projeto – o projeto já entregue na Câmara Municipal de Lisboa, as condicionantes urbanísticas, os requisitos de classificação do estabelecimento hoteleiro, as normas do operador e os limites orçamentais – de modo a preparar o desenvolvimento do Estudo Prévio.", "key_activities_html": "<ul><li><p>Visita ao local / reunião com o cliente e o Rockwell Group;</p></li><li><p>Análise do projeto já entregue na Câmara Municipal de Lisboa;</p></li><li><p>Consulta de elementos sobre o edifício (no arquivo municipal ou outros);</p></li><li><p>Consulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;</p></li><li><p>Eventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisita ao local / reunião com o cliente e o Rockwell Group;\n\n\n\nAnálise do projeto já entregue na Câmara Municipal de Lisboa;\n\n\n\nConsulta de elementos sobre o edifício (no arquivo municipal ou outros);\n\n\n\nConsulta da legislação aplicável à intervenção, incluindo o regime jurídico dos empreendimentos turísticos e os requisitos de classificação dos estabelecimentos hoteleiros;\n\n\n\nEventual agendamento de reunião com a Câmara Municipal de Lisboa para esclarecimentos.\n\n", "stage_approval_html": "<p>No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p><p><strong>NOTA:</strong> Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado.</p>", "stage_approval_text": "No final desta fase, o cliente aprova o Programa, que servirá de referência para o Estudo Prévio. O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.\n\nNOTA: Para iniciar o estudo serão necessárias bases de trabalho fundamentais para a sua realização, designadamente o levantamento arquitetónico do edifício, feito por técnico credenciado."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch db9736ec-ce7b-4482-8750-5a234a3b4be2'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Aprovação do Programa\nLevantamento arquitetónico do edifício em formato DWG (editável)\nNomes e contactos das equipas escolhidas para o projeto", "deliverables": "Relatório da fase com descrição escrita do projeto.\nLayout final com todas as alterações pretendidas pelo Cliente.\nPlantas de todos os pisos, cortes e alçados – escala 1:100.\nQuadro de áreas e de quartos.\nEntrega em formato digital e 2 conjuntos impressos.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa, vamos elaborar, em articulação com o designer de interiores, o Estudo Prévio do hotel, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.</p><p>Iremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.</p><p>É ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa, vamos elaborar, em articulação com o designer de interiores, o Estudo Prévio do hotel, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.\n\nIremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.\n\nÉ ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "key_activities_html": "<ul><li><p>Reunião inicial com o Cliente e o designer de interiores para confirmar o Programa e os objetivos do projeto;</p></li><li><p>Apresentação de toda a equipa do projeto, das especialidades ao design de interiores;</p></li><li><p>Estudos do layout definitivo dos vários pisos e dos quartos;</p></li><li><p>Estudos de cortes, alçados e volumetria;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;</p></li><li><p>Coordenação da equipa de projeto e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nReunião inicial com o Cliente e o designer de interiores para confirmar o Programa e os objetivos do projeto;\n\n\n\nApresentação de toda a equipa do projeto, das especialidades ao design de interiores;\n\n\n\nEstudos do layout definitivo dos vários pisos e dos quartos;\n\n\n\nEstudos de cortes, alçados e volumetria;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;\n\n\n\nCoordenação da equipa de projeto e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.\n\n", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb WHERE id='2d9b0662-984c-41a7-b518-97baea89035b' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"client_info": "Aprovação do Programa\nDesenhos entregues na CML em formato DWG (editável)\nNomes e contactos das equipas escolhidas para o projeto", "deliverables": "Relatório da fase com descrição escrita do projeto.\nLayout final com todas as alterações pretendidas pelo Cliente.\nPlantas de todos os pisos, cortes e alçados – escala 1:100.\nQuadro de áreas e de quartos.\nEntrega em formato digital e 2 conjuntos impressos.", "headingLevel": "h2", "objective_html": "<p>Depois de definido e aprovado o Programa, vamos rever e ajustar, em conjunto com o Rockwell Group, o projeto já entregue na Câmara Municipal de Lisboa, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.</p><p>Iremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.</p><p>É ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.</p>", "objective_text": "Depois de definido e aprovado o Programa, vamos rever e ajustar, em conjunto com o Rockwell Group, o projeto já entregue na Câmara Municipal de Lisboa, desenvolvendo os conceitos definidos e apresentando soluções através de desenhos e outros elementos que facilitem a compreensão do projeto, da sua organização e da sua aparência final.\n\nIremos definir a globalidade da intervenção, fixando o layout final com todas as alterações pretendidas pelo Cliente, dentro do contexto da legislação em vigor para o local, e estudar a melhor estratégia de encaminhar o processo para a obtenção da aprovação camarária.\n\nÉ ainda nosso papel consultar os projetistas das especialidades para, em conjunto com estes, estudar as soluções do ponto de vista técnico, construtivo e de custos.", "key_activities_html": "<ul><li><p>Reunião inicial com o Cliente para identificar as alterações ao projeto entregue na CML;</p></li><li><p>Apresentação de toda a equipa do projeto, das especialidades ao Rockwell Group;</p></li><li><p>Estudos do layout definitivo dos vários pisos e dos quartos;</p></li><li><p>Estudos de cortes, alçados e volumetria;</p></li><li><p>Cálculo de áreas, cérceas e índices a cumprir;</p></li><li><p>Verificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;</p></li><li><p>Coordenação da equipa local e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nReunião inicial com o Cliente para identificar as alterações ao projeto entregue na CML;\n\n\n\nApresentação de toda a equipa do projeto, das especialidades ao Rockwell Group;\n\n\n\nEstudos do layout definitivo dos vários pisos e dos quartos;\n\n\n\nEstudos de cortes, alçados e volumetria;\n\n\n\nCálculo de áreas, cérceas e índices a cumprir;\n\n\n\nVerificação preliminar dos requisitos de classificação do estabelecimento hoteleiro;\n\n\n\nCoordenação da equipa local e verificação da compatibilização de todos os projetos. Todas as alterações pretendidas pelo Cliente devem ser fechadas até à conclusão desta fase.\n\n", "stage_approval_html": "<p>Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "Prevemos ir ao encontro dos seus objetivos através da apresentação de uma proposta de estudo prévio, desenvolvida durante o tempo estimado e com os recursos previstos no planeamento apresentado. A nossa equipa fará as necessárias afinações de forma a obter a sua total satisfação, desde que estas estejam dentro do número de horas previsto na nossa proposta de honorários.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch 2d9b0662-984c-41a7-b518-97baea89035b'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nElementos ou autorizações em nome do Cliente que o Arquiteto venha a solicitar por escrito", "deliverables": "Plantas com organização geral dos espaços e indicação de materiais – escala 1:100.\nCortes e alçados – escala 1:100.\nMemória descritiva e Plano de Acessibilidades.\nProcesso de licenciamento submetido no portal Loja Lisboa.\nEntrega em formato digital e conjuntos impressos na quantidade requerida pela CML.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores e com os projetistas de especialidades, e da elaboração dos elementos solicitados pela Câmara Municipal e demais entidades para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos dos estabelecimentos hoteleiros.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o designer de interiores e com os projetistas de especialidades, e da elaboração dos elementos solicitados pela Câmara Municipal e demais entidades para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos dos estabelecimentos hoteleiros.\n\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\n\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "key_activities_html": "<ul><li><p>Desenvolvimento dos desenhos a entregar na CML e outras entidades;</p></li><li><p>Reuniões com as equipas de engenharia e especialistas para integração das especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital;</p></li><li><p>Submissão do processo e acompanhamento junto da CML;</p></li><li><p>Acompanhamento do parecer do Turismo de Portugal, I.P., obrigatório no licenciamento do estabelecimento hoteleiro;</p></li><li><p>Resposta a eventuais notificações, desde que motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra. Alterações pedidas pelo Cliente nesta fase são objeto de nova proposta, salvo se exigidas pela CML ou outra entidade.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDesenvolvimento dos desenhos a entregar na CML e outras entidades;\n\n\n\nReuniões com as equipas de engenharia e especialistas para integração das especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital;\n\n\n\nSubmissão do processo e acompanhamento junto da CML;\n\n\n\nAcompanhamento do parecer do Turismo de Portugal, I.P., obrigatório no licenciamento do estabelecimento hoteleiro;\n\n\n\nResposta a eventuais notificações, desde que motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra. Alterações pedidas pelo Cliente nesta fase são objeto de nova proposta, salvo se exigidas pela CML ou outra entidade.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb WHERE id='a1ceee28-26da-4fac-a0e0-6bd5c5f96403' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"client_info": "Aprovação do PIP pela Câmara Municipal de Lisboa\nProjetos de especialidades, a contratar pelo promotor\nElementos ou autorizações em nome do Cliente que o Arquiteto venha a solicitar por escrito", "deliverables": "Plantas com organização geral dos espaços e indicação de materiais – escala 1:100.\nCortes e alçados – escala 1:100.\nMemória descritiva e Plano de Acessibilidades.\nProcesso de licenciamento submetido no portal Loja Lisboa.\nEntrega em formato digital e conjuntos impressos na quantidade requerida pela CML.", "headingLevel": "h2", "objective_html": "<p>A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o Rockwell Group e com os projetistas de especialidades, e da elaboração dos elementos solicitados pela Câmara Municipal e demais entidades para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos dos estabelecimentos hoteleiros.</p><p>Serão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.</p><p>Definidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.</p>", "objective_text": "A fase de projeto de licenciamento consiste no desenvolvimento da proposta do PIP aprovado, através da interação com o Rockwell Group e com os projetistas de especialidades, e da elaboração dos elementos solicitados pela Câmara Municipal e demais entidades para a instrução e submissão do processo, de acordo com a legislação aplicável, incluindo os requisitos dos estabelecimentos hoteleiros.\n\nSerão definidas nesta fase as soluções construtivas e será elaborado um estudo preliminar da integração das infraestruturas (gás, águas, esgotos, ventilação, eletricidade, telecomunicações) e, em especial, das estruturas e das condicionantes térmicas e acústicas na construção.\n\nDefinidas as soluções em conjunto com os projetistas de especialidades, serão feitos os necessários ajustes nos desenhos de arquitetura e preparados todos os elementos necessários (peças escritas, peças desenhadas e documentos) à submissão do processo de licenciamento no portal da Câmara Municipal de Lisboa.", "key_activities_html": "<ul><li><p>Desenvolvimento dos desenhos a entregar na CML e outras entidades;</p></li><li><p>Reuniões com as equipas de engenharia e especialistas para integração das especialidades;</p></li><li><p>Projeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital;</p></li><li><p>Submissão do processo e acompanhamento junto da CML;</p></li><li><p>Acompanhamento do parecer do Turismo de Portugal, I.P., obrigatório no licenciamento do estabelecimento hoteleiro;</p></li><li><p>Resposta a eventuais notificações, desde que motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra. Alterações pedidas pelo Cliente nesta fase são objeto de nova proposta, salvo se exigidas pela CML ou outra entidade.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nDesenvolvimento dos desenhos a entregar na CML e outras entidades;\n\n\n\nReuniões com as equipas de engenharia e especialistas para integração das especialidades;\n\n\n\nProjeto de Arquitetura e Plano de Acessibilidades – peças desenhadas e peças escritas em formato digital;\n\n\n\nSubmissão do processo e acompanhamento junto da CML;\n\n\n\nAcompanhamento do parecer do Turismo de Portugal, I.P., obrigatório no licenciamento do estabelecimento hoteleiro;\n\n\n\nResposta a eventuais notificações, desde que motivadas por lapsos da equipa de projeto e não por opções de projeto impostas pelo dono de obra. Alterações pedidas pelo Cliente nesta fase são objeto de nova proposta, salvo se exigidas pela CML ou outra entidade.\n\n", "stage_approval_html": "<p>A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "A nossa proposta para a fase de licenciamento é apresentada considerando que a proposta de PIP é aprovada. Caso o licenciamento tenha de ser diferente da proposta apresentada como PIP e tenham de ser elaborados novos estudos, a nossa proposta de honorários e o calendário previsto terão de ser revistos.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch a1ceee28-26da-4fac-a0e0-6bd5c5f96403'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nEquipa de Gestão de Projeto selecionada e operacional para lançar o concurso de obra, analisar propostas e selecionar o empreiteiro", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:100, 1:20, 1:10, 1:5 e 1:1).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais (Excel, A4).", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com o projeto aprovado pela CML e demais entidades, as intenções do promotor e do design de interiores e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para os quartos.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que servirá de base aos pedidos de orçamento aos construtores, e uma Estimativa Orçamental de referência. Faremos também a compatibilização final do projeto de Arquitetura com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com o projeto aprovado pela CML e demais entidades, as intenções do promotor e do design de interiores e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para os quartos.\n\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que servirá de base aos pedidos de orçamento aos construtores, e uma Estimativa Orçamental de referência. Faremos também a compatibilização final do projeto de Arquitetura com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas de arquitetura (planta geral e de acabamentos) – escala 1:100;</p></li><li><p>Plantas de tetos refletidos com materiais, iluminação e coordenação com as especialidades – escala 1:100;</p></li><li><p>Cortes gerais e de áreas específicas – escala 1:100;</p></li><li><p>Detalhes de zonas específicas (instalações sanitárias, cozinhas, etc.) – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo;</p></li><li><p>Detalhes construtivos às escalas 1:10, 1:5 e 1:1;</p></li><li><p>Compatibilização final de todos os projetos de especialidades, com as reuniões necessárias;</p></li><li><p>Informação de apoio à preparação do lançamento do concurso de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas de arquitetura (planta geral e de acabamentos) – escala 1:100;\n\n\n\nPlantas de tetos refletidos com materiais, iluminação e coordenação com as especialidades – escala 1:100;\n\n\n\nCortes gerais e de áreas específicas – escala 1:100;\n\n\n\nDetalhes de zonas específicas (instalações sanitárias, cozinhas, etc.) – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo;\n\n\n\nDetalhes construtivos às escalas 1:10, 1:5 e 1:1;\n\n\n\nCompatibilização final de todos os projetos de especialidades, com as reuniões necessárias;\n\n\n\nInformação de apoio à preparação do lançamento do concurso de obra.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes. Alterações ao projeto nesta fase são objeto de proposta de honorários específica.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes. Alterações ao projeto nesta fase são objeto de proposta de honorários específica.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb WHERE id='1085f5cd-1556-4386-89c4-2d94d46d18fc' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"client_info": "Aprovação do Projeto de Licenciamento\nLimites do custo da obra\nEquipa de Gestão de Projeto selecionada e operacional para lançar o concurso de obra, analisar propostas e selecionar o empreiteiro", "deliverables": "Peças desenhadas do projeto de execução (escalas 1:100, 1:20, 1:10, 1:5 e 1:1).\nDescrição de acabamentos e equipamentos.\nMapa de Quantidades e Medições.\nEstimativa Orçamental.\nCaderno de Encargos e Condições Técnicas Especiais (Excel, A4).", "headingLevel": "h2", "objective_html": "<p>Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com o projeto aprovado pela CML e demais entidades, as intenções do promotor e do Rockwell Group e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.</p><p>Iremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para os quartos.</p><p>A partir desses elementos é elaborado um Mapa de Quantidades e Medições, que servirá de base aos pedidos de orçamento aos construtores, e uma Estimativa Orçamental de referência. Faremos também a compatibilização final do projeto de Arquitetura com os diferentes projetos de especialidades.</p>", "objective_text": "Esta fase consiste no desenvolvimento do projeto de arquitetura, em que iremos desenvolver soluções estéticas e construtivas de acordo com o projeto aprovado pela CML e demais entidades, as intenções do promotor e do Rockwell Group e as condicionantes do Projeto, ditadas pela legislação em vigor, pelos condicionalismos técnicos e pelos limites do custo da obra.\n\nIremos elaborar desenhos e elementos escritos que irão especificar todos os materiais e trabalhos necessários para a execução da obra. Está previsto que haja repetição das soluções, acabamentos e equipamentos a definir para os quartos.\n\nA partir desses elementos é elaborado um Mapa de Quantidades e Medições, que servirá de base aos pedidos de orçamento aos construtores, e uma Estimativa Orçamental de referência. Faremos também a compatibilização final do projeto de Arquitetura com os diferentes projetos de especialidades.", "key_activities_html": "<ul><li><p>Plantas de arquitetura (planta geral e de acabamentos) – escala 1:100;</p></li><li><p>Plantas de tetos refletidos com materiais, iluminação e coordenação com as especialidades – escala 1:100;</p></li><li><p>Cortes gerais e de áreas específicas – escala 1:100;</p></li><li><p>Detalhes de zonas específicas (instalações sanitárias, cozinhas, etc.) – escala 1:20;</p></li><li><p>Mapas de vãos e de mobiliário fixo;</p></li><li><p>Detalhes construtivos às escalas 1:10, 1:5 e 1:1;</p></li><li><p>Compatibilização final de todos os projetos de especialidades, com as reuniões necessárias;</p></li><li><p>Informação de apoio à preparação do lançamento do concurso de obra.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nPlantas de arquitetura (planta geral e de acabamentos) – escala 1:100;\n\n\n\nPlantas de tetos refletidos com materiais, iluminação e coordenação com as especialidades – escala 1:100;\n\n\n\nCortes gerais e de áreas específicas – escala 1:100;\n\n\n\nDetalhes de zonas específicas (instalações sanitárias, cozinhas, etc.) – escala 1:20;\n\n\n\nMapas de vãos e de mobiliário fixo;\n\n\n\nDetalhes construtivos às escalas 1:10, 1:5 e 1:1;\n\n\n\nCompatibilização final de todos os projetos de especialidades, com as reuniões necessárias;\n\n\n\nInformação de apoio à preparação do lançamento do concurso de obra.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes. Alterações ao projeto nesta fase são objeto de proposta de honorários específica.</p><p>O Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes.</p>", "stage_approval_text": "NOTA: É importante facultar-nos informação quanto aos limites do custo da obra, de forma a tomar decisões de acordo com as condicionantes. Alterações ao projeto nesta fase são objeto de proposta de honorários específica.\n\nO Cliente dispõe de 5 dias úteis após a entrega para aprovar a fase. Na ausência de resposta findo este prazo, a fase considera-se aprovada por ambas as partes."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch 1085f5cd-1556-4386-89c4-2d94d46d18fc'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"client_info": "Concurso de obra por convite lançado pela equipa de Gestão de Projecto, com empresas de experiência adequada\nResultados do concurso, escolha do empreiteiro, calendarização e contrato de obra (Gestão de Projecto)\nReportagens fotográficas semanais e relatórios mensais do estado da obra, incluindo análise financeira", "deliverables": "Desenhos de esclarecimento ou alteração decorrentes da construção, à escala adequada\nDocumentação para construção\nEntrega em formato digital", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura em todas as suas componentes e o esclarecimento de eventuais dúvidas.</p><p>Os honorários desta fase consideram o apoio de um arquiteto do atelier durante a construção, faturado mensalmente; a duração será confirmada quando o prazo de obra estiver definido.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o designer de interiores e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura em todas as suas componentes e o esclarecimento de eventuais dúvidas.\n\nOs honorários desta fase consideram o apoio de um arquiteto do atelier durante a construção, faturado mensalmente; a duração será confirmada quando o prazo de obra estiver definido.", "key_activities_html": "<ul><li><p>Visitas à obra com periodicidade máxima semanal, em função das fases e necessidades da obra;</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral e informações complementares de leitura do projeto;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura;</p></li><li><p>Apoio ao dono de obra na verificação da qualidade dos materiais e da execução dos trabalhos;</p></li><li><p>Pormenores adicionais que se tornem necessários no decorrer da construção.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisitas à obra com periodicidade máxima semanal, em função das fases e necessidades da obra;\n\n\n\nResposta a dúvidas do Empreiteiro Geral e informações complementares de leitura do projeto;\n\n\n\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\n\n\n\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura;\n\n\n\nApoio ao dono de obra na verificação da qualidade dos materiais e da execução dos trabalhos;\n\n\n\nPormenores adicionais que se tornem necessários no decorrer da construção.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}'::jsonb WHERE id='05f8f35b-f616-4f6a-8660-1ba951e00232' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"client_info": "Concurso de obra por convite lançado pela equipa de Gestão de Projecto, com empresas de experiência adequada\nResultados do concurso, escolha do empreiteiro, calendarização e contrato de obra (Gestão de Projecto)\nReportagens fotográficas semanais e relatórios mensais do estado da obra, incluindo análise financeira", "deliverables": "Desenhos de esclarecimento ou alteração decorrentes da construção, à escala adequada\nDocumentação para construção\nEntrega em formato digital", "objective_html": "<p>Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o Rockwell Group e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura em todas as suas componentes e o esclarecimento de eventuais dúvidas.</p><p>Os honorários desta fase consideram o apoio de um arquiteto do atelier durante a construção, faturado mensalmente; a duração será confirmada quando o prazo de obra estiver definido.</p>", "objective_text": "Na fase de construção, faremos o acompanhamento da obra através de reuniões com o Empreiteiro Geral, a Fiscalização, o Rockwell Group e os restantes técnicos responsáveis pelos projetos de especialidades, tendo como objetivo garantir a correta interpretação do projeto de Arquitetura em todas as suas componentes e o esclarecimento de eventuais dúvidas.\n\nOs honorários desta fase consideram o apoio de um arquiteto do atelier durante a construção, faturado mensalmente; a duração será confirmada quando o prazo de obra estiver definido.", "key_activities_html": "<ul><li><p>Visitas à obra com periodicidade máxima semanal, em função das fases e necessidades da obra;</p></li><li><p>Resposta a dúvidas do Empreiteiro Geral e informações complementares de leitura do projeto;</p></li><li><p>Análise e parecer de desenhos de preparação de obra relativos à arquitetura;</p></li><li><p>Análise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura;</p></li><li><p>Apoio ao dono de obra na verificação da qualidade dos materiais e da execução dos trabalhos;</p></li><li><p>Pormenores adicionais que se tornem necessários no decorrer da construção.</p></li></ul><p></p>", "key_activities_text": "\n\n\n\nVisitas à obra com periodicidade máxima semanal, em função das fases e necessidades da obra;\n\n\n\nResposta a dúvidas do Empreiteiro Geral e informações complementares de leitura do projeto;\n\n\n\nAnálise e parecer de desenhos de preparação de obra relativos à arquitetura;\n\n\n\nAnálise e parecer de pedidos de aprovação de materiais e equipamentos relativos à arquitetura;\n\n\n\nApoio ao dono de obra na verificação da qualidade dos materiais e da execução dos trabalhos;\n\n\n\nPormenores adicionais que se tornem necessários no decorrer da construção.\n\n", "stage_approval_html": "<p><strong>NOTA:</strong> A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra.</p>", "stage_approval_text": "NOTA: A Assistência Técnica não constitui uma Fiscalização da Obra, nem a Gestão da Obra. Em caso de suspensão, interrupção ou cancelamento da obra, não serão cobrados os honorários relativos à Assistência Técnica à Obra."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch 05f8f35b-f616-4f6a-8660-1ba951e00232'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"html": "<p>Os nossos honorários são calculados em função de uma estimativa do tempo e dos recursos a utilizar para proceder à elaboração do projeto, de acordo com o planeamento apresentado. Os valores correspondem ao âmbito de serviços descrito nesta proposta, organizado por fases, e não incluem o IVA à taxa legal em vigor.</p><p>A Assistência Técnica à obra é faturada mensalmente, no valor de 3 500 € por mês, acrescido de IVA, e considera o apoio de um arquiteto do atelier durante a construção, com visitas à obra de periodicidade máxima semanal. Nesta fase não é ainda conhecido o prazo de obra, pelo que a presente proposta considera 12 meses de assistência (42 000 €); o número de meses será ajustado ao prazo de obra definido, mantendo-se o valor mensal. Visitas adicionais solicitadas pelo Cliente são faturadas à hora técnica.</p>", "text": "Os nossos honorários são calculados em função de uma estimativa do tempo e dos recursos a utilizar para proceder à elaboração do projeto, de acordo com o planeamento apresentado. Os valores correspondem ao âmbito de serviços descrito nesta proposta, organizado por fases, e não incluem o IVA à taxa legal em vigor.\n\nA Assistência Técnica à obra é faturada mensalmente, no valor de 3 500 € por mês, acrescido de IVA, e considera o apoio de um arquiteto do atelier durante a construção, com visitas à obra de periodicidade máxima semanal. Nesta fase não é ainda conhecido o prazo de obra, pelo que a presente proposta considera 12 meses de assistência (42 000 €); o número de meses será ajustado ao prazo de obra definido, mantendo-se o valor mensal. Visitas adicionais solicitadas pelo Cliente são faturadas à hora técnica."}'::jsonb WHERE id='5f27cd29-037d-44f7-a8cc-61f9b8c992a0' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"html": "<p>Os nossos honorários são calculados em função de uma estimativa do tempo e dos recursos a utilizar para proceder à elaboração do projeto, de acordo com o planeamento apresentado. Os valores correspondem ao âmbito de serviços descrito nesta proposta, organizado por fases, e não incluem o IVA à taxa legal em vigor.</p><p>A Assistência Técnica à obra é faturada mensalmente, no valor de 2 200 € por mês, acrescido de IVA, e considera o apoio de um arquiteto do atelier durante a construção, com visitas à obra de periodicidade máxima semanal. Nesta fase não é ainda conhecido o prazo de obra, pelo que a presente proposta considera um mês de assistência; o número de meses será ajustado ao prazo de obra definido, mantendo-se o valor mensal. Visitas adicionais solicitadas pelo Cliente são faturadas à hora técnica.</p>", "text": "Os nossos honorários são calculados em função de uma estimativa do tempo e dos recursos a utilizar para proceder à elaboração do projeto, de acordo com o planeamento apresentado. Os valores correspondem ao âmbito de serviços descrito nesta proposta, organizado por fases, e não incluem o IVA à taxa legal em vigor.\n\nA Assistência Técnica à obra é faturada mensalmente, no valor de 2 200 € por mês, acrescido de IVA, e considera o apoio de um arquiteto do atelier durante a construção, com visitas à obra de periodicidade máxima semanal. Nesta fase não é ainda conhecido o prazo de obra, pelo que a presente proposta considera um mês de assistência; o número de meses será ajustado ao prazo de obra definido, mantendo-se o valor mensal. Visitas adicionais solicitadas pelo Cliente são faturadas à hora técnica."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch 5f27cd29-037d-44f7-a8cc-61f9b8c992a0'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><p>A PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.</p><h3>Projetos de especialidades</h3><p>Os projetos de especialidades não fazem parte desta proposta de honorários. São elaborados por equipas externas à Pedra Silva Arquitectos, contratadas diretamente pelo Cliente, e cada equipa apresenta o seu preço separadamente. A coordenação dos projetos de especialidades com o projeto de arquitetura está incluída na nossa prestação de serviços. Quando for necessário recorrer a peritos, consultores ou engenharias, o Arquiteto aconselha o Cliente sobre possíveis candidatos adequados às necessidades do projeto.</p><h3>Encerramentos</h3><p>O atelier encerra entre o Natal e o Ano Novo e nos feriados nacionais e locais de Lisboa; os prazos indicados serão ajustados em conformidade.</p><p>As condições aqui apresentadas regem-se pela legislação portuguesa aplicável. Qualquer alteração ao âmbito ou ao calendário será formalizada por escrito entre as partes.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\n\nA PSA é a autora e coordenadora do projeto de arquitetura, em parceria com o designer de interiores indicado pelo Cliente. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Cliente e pelo designer de interiores.\n\nProjetos de especialidades\n\nOs projetos de especialidades não fazem parte desta proposta de honorários. São elaborados por equipas externas à Pedra Silva Arquitectos, contratadas diretamente pelo Cliente, e cada equipa apresenta o seu preço separadamente. A coordenação dos projetos de especialidades com o projeto de arquitetura está incluída na nossa prestação de serviços. Quando for necessário recorrer a peritos, consultores ou engenharias, o Arquiteto aconselha o Cliente sobre possíveis candidatos adequados às necessidades do projeto.\n\nEncerramentos\n\nO atelier encerra entre o Natal e o Ano Novo e nos feriados nacionais e locais de Lisboa; os prazos indicados serão ajustados em conformidade.\n\nAs condições aqui apresentadas regem-se pela legislação portuguesa aplicável. Qualquer alteração ao âmbito ou ao calendário será formalizada por escrito entre as partes."}'::jsonb WHERE id='bcaf03b4-130e-434e-ade5-f839bc9e53ae' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"html": "<p>A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.</p><p>A PSA atua como parceiro local do Rockwell Group. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Rockwell Group e pelo Cliente.</p><h3>Projetos de especialidades</h3><p>Os projetos de especialidades não fazem parte desta proposta de honorários. São elaborados por equipas externas à Pedra Silva Arquitectos, contratadas diretamente pelo Cliente, e cada equipa apresenta o seu preço separadamente. A coordenação dos projetos de especialidades com o projeto de arquitetura está incluída na nossa prestação de serviços. Quando for necessário recorrer a peritos, consultores ou engenharias, o Arquiteto aconselha o Cliente sobre possíveis candidatos adequados às necessidades do projeto.</p><h3>Encerramentos</h3><p>O atelier encerra entre o Natal e o Ano Novo e nos feriados nacionais e locais de Lisboa; os prazos indicados serão ajustados em conformidade.</p><p>As condições aqui apresentadas regem-se pela legislação portuguesa aplicável. Qualquer alteração ao âmbito ou ao calendário será formalizada por escrito entre as partes.</p>", "text": "A presente proposta baseia-se nos parâmetros e no âmbito do projeto aqui descritos e na informação disponível à data da sua elaboração. Alterações relevantes ao programa, às áreas, ao âmbito do projeto, aos requisitos legais ou às instruções do cliente poderão implicar a revisão do âmbito dos serviços e dos respetivos honorários.\n\nA PSA atua como parceiro local do Rockwell Group. O cumprimento dos prazos de cada fase depende da receção atempada dos elementos a fornecer pelo Rockwell Group e pelo Cliente.\n\nProjetos de especialidades\n\nOs projetos de especialidades não fazem parte desta proposta de honorários. São elaborados por equipas externas à Pedra Silva Arquitectos, contratadas diretamente pelo Cliente, e cada equipa apresenta o seu preço separadamente. A coordenação dos projetos de especialidades com o projeto de arquitetura está incluída na nossa prestação de serviços. Quando for necessário recorrer a peritos, consultores ou engenharias, o Arquiteto aconselha o Cliente sobre possíveis candidatos adequados às necessidades do projeto.\n\nEncerramentos\n\nO atelier encerra entre o Natal e o Ano Novo e nos feriados nacionais e locais de Lisboa; os prazos indicados serão ajustados em conformidade.\n\nAs condições aqui apresentadas regem-se pela legislação portuguesa aplicável. Qualquer alteração ao âmbito ou ao calendário será formalizada por escrito entre as partes."}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch bcaf03b4-130e-434e-ade5-f839bc9e53ae'; END IF;
UPDATE public.psa_proposal_blocks SET content_rich='{"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Projeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&amp;E), a cargo do designer de interiores indicado pelo Cliente;</p></li><li><p>Despesas de deslocação fora do concelho de Lisboa (voos, alojamento, refeições e outras), pagas pelo Cliente mediante apresentação de fatura ou recibo e acordo prévio;</p></li><li><p>Projetos de engenharia e especialidades, peritos e consultores, a contratar diretamente pelo Cliente;</p></li><li><p>Levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos;</p></li><li><p>Taxas camarárias, licenças e encargos administrativos;</p></li><li><p>Gestão de projeto, direção técnica, coordenação de segurança e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais e imagens 3D;</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos;</p></li><li><p>Processo de classificação do estabelecimento hoteleiro junto do Turismo de Portugal após a conclusão da obra, e autorização de utilização para fins turísticos;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\n\n\n\n\nProjeto de design de interiores, incluindo mobiliário, equipamento e decoração (FF&E), a cargo do designer de interiores indicado pelo Cliente;\n\n\n\nDespesas de deslocação fora do concelho de Lisboa (voos, alojamento, refeições e outras), pagas pelo Cliente mediante apresentação de fatura ou recibo e acordo prévio;\n\n\n\nProjetos de engenharia e especialidades, peritos e consultores, a contratar diretamente pelo Cliente;\n\n\n\nLevantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos;\n\n\n\nTaxas camarárias, licenças e encargos administrativos;\n\n\n\n\n\n\n\nGestão de projeto, direção técnica, coordenação de segurança e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais e imagens 3D;\n\n\n\n\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos;\n\n\n\nProcesso de classificação do estabelecimento hoteleiro junto do Turismo de Portugal após a conclusão da obra, e autorização de utilização para fins turísticos;\n\n\n\nCertificação energética e acústica.\n\n", "headingLevel": "h2"}'::jsonb WHERE id='a8ab2c8e-880d-4965-a4e6-065994959ed3' AND proposal_id='3d0db6b3-4bf5-4681-a875-c553f8c64656' AND content_rich='{"html": "<p>Estão excluídos da proposta:</p><ul><li><p>IVA à taxa legal em vigor;</p></li><li><p>Programa Base (Fase 1), a definir pelo Cliente e pelo Rockwell Group;</p></li><li><p>Conceção do hotel, a cargo do Rockwell Group;</p></li><li><p>Despesas de deslocação fora do concelho de Lisboa (voos, alojamento, refeições e outras), pagas pelo Cliente mediante apresentação de fatura ou recibo e acordo prévio;</p></li><li><p>Projetos de engenharia e especialidades, peritos e consultores, a contratar diretamente pelo Cliente;</p></li><li><p>Levantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos;</p></li><li><p>Taxas camarárias, licenças e encargos administrativos;</p></li><li><p>Preparação e lançamento de concurso de empreitadas;</p></li><li><p>Gestão de projeto, direção técnica, coordenação de segurança e fiscalização da obra;</p></li><li><p>Elaboração de desenhos de preparação de obra;</p></li><li><p>Maquetes profissionais e imagens 3D;</p></li><li><p>Projeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&amp;E);</p></li><li><p>Projetos especiais (cozinhas técnicas, piscinas e spa);</p></li><li><p>Pedidos ou negociações para a obtenção de financiamentos;</p></li><li><p>Processo de classificação do estabelecimento hoteleiro junto do Turismo de Portugal após a conclusão da obra, e autorização de utilização para fins turísticos;</p></li><li><p>Certificação energética e acústica.</p></li></ul><p></p>", "text": "Estão excluídos da proposta:\n\n\n\n\n\nIVA à taxa legal em vigor;\n\n\n\nPrograma Base (Fase 1), a definir pelo Cliente e pelo Rockwell Group;\n\n\n\nConceção do hotel, a cargo do Rockwell Group;\n\n\n\nDespesas de deslocação fora do concelho de Lisboa (voos, alojamento, refeições e outras), pagas pelo Cliente mediante apresentação de fatura ou recibo e acordo prévio;\n\n\n\nProjetos de engenharia e especialidades, peritos e consultores, a contratar diretamente pelo Cliente;\n\n\n\nLevantamentos topográficos e arquitetónicos, estudos geotécnicos e geológicos;\n\n\n\nTaxas camarárias, licenças e encargos administrativos;\n\n\n\nPreparação e lançamento de concurso de empreitadas;\n\n\n\nGestão de projeto, direção técnica, coordenação de segurança e fiscalização da obra;\n\n\n\nElaboração de desenhos de preparação de obra;\n\n\n\nMaquetes profissionais e imagens 3D;\n\n\n\nProjeto de decoração de interiores e de mobiliário, equipamento e decoração (FF&E);\n\n\n\nProjetos especiais (cozinhas técnicas, piscinas e spa);\n\n\n\nPedidos ou negociações para a obtenção de financiamentos;\n\n\n\nProcesso de classificação do estabelecimento hoteleiro junto do Turismo de Portugal após a conclusão da obra, e autorização de utilização para fins turísticos;\n\n\n\nCertificação energética e acústica.\n\n", "headingLevel": "h2"}'::jsonb AND NOT is_locked; GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'Before-image mismatch a8ab2c8e-880d-4965-a4e6-065994959ed3'; END IF;
END $edit$;
COMMIT;
